    void collect(View v,Set<Bitmap> images){if(v instanceof ImageView&&((ImageView)v).getDrawable() instanceof BitmapDrawable)images.add(((BitmapDrawable)((ImageView)v).getDrawable()).getBitmap());if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)collect(((ViewGroup)v).getChildAt(i),images);}
